class Node:
    def __init__(self, key):
        self.key = key
        self.left = self.right = None

def insert(node, key):
    if node is None:
        return Node(key)
    if key < node.key:
        node.left = insert(node.left, key)
    elif key > node.key:
        node.right = insert(node.right, key)
    return node

def collect(node, kind):
    if node is None:
        return []
    left, right = collect(node.left, kind), collect(node.right, kind)
    here = [node.key]
    return {"pre": here + left + right, "in": left + here + right, "post": left + right + here}[kind]

def height(node):
    return -1 if node is None else 1 + max(height(node.left), height(node.right))

def leaves(node):
    if node is None:
        return 0
    if node.left is None and node.right is None:
        return 1
    return leaves(node.left) + leaves(node.right)

def build(keys):
    root = None
    for key in keys:
        root = insert(root, key)
    return root

root = build([5, 3, 8, 1, 4])
assert collect(root, "in") == [1, 3, 4, 5, 8]
assert collect(root, "pre") == [5, 3, 1, 4, 8]
assert collect(root, "post") == [1, 4, 3, 8, 5]
assert height(root) == 2
assert height(build([1, 2, 3, 4, 5, 6])) == 5
side = build([5, 2, 7, 6])
assert collect(side, "pre") == [5, 2, 7, 6]
assert height(side) == 2 and leaves(side) == 2
assert leaves(build([4, 2, 6, 1, 3, 5, 7])) == 4
